import re
from fixar import AR
W={'اآليت':'الآتي','يأيت':'يأتي','العامنية':'العمانية','العامنيون':'العمانيون','العامنيني':'العمانيين','املفردتني':'المفردتين','العنرص':'العنصر','ميثل':'يمثل','بهال':'بهلا','السليامين':'السليماني','املعويل':'المعولي','يشري':'يشير','تشري':'تشير','إليهام':'إليهما','يبني':'يبين','الخرب':'الخبر','للخرب':'للخبر','أقىص':'أقصى','دائريت':'دائرتي','تدشني':'تدشين','لتدشني':'لتدشين','أسامء':'أسماء','القوسني':'القوسين','لألبحاث':'للأبحاث','الرتتيب':'الترتيب','األكسجني':'الأكسجين','وكرثتها':'وكثرتها','العامنيني':'العمانيين','تطهري':'تطهير','توطني':'توطين','تغري':'تغير','العارش':'العاشر','امليالديني':'الميلاديين','الرشطة':'الشرطة','املامرسات':'الممارسات','اآلتيني':'الآتيين','واملشار':'والمشار','مثالني':'مثالين','لغريب':'لغربي','النيجريي':'النيجيري','باألرجنتني':'بالأرجنتين','ييل':'يلي','وغريها':'وغيرها','الهنايئ':'الهنائي','الرحامين':'الرحماني','التاليتني':'التاليتين','املنطقتني':'المنطقتين','العوايب':'العوابي','الربكانية':'البركانية','تقيض':'تقضي','رصاعات':'صراعات','املناوئني':'المناوئين','للربتغاليني':'للبرتغاليين','انطالقا':'انطلاقًا','الربتغال':'البرتغال','برتغايل':'برتغالي','رشوط':'شروط','البرتولية':'البترولية','ترض':'تضر','معدالت':'معدلات','يعترب':'يعتبر','تعترب':'تعتبر','أحيايئ':'أحيائي','تفرس':'تفسر','الرتفاع':'لارتفاع','املحافظتني':'المحافظتين','عرصهم':'عصرهم','ميكننا':'يمكننا','الرحالت':'الرحلات','أمري':'أمير','الرشع':'الشرع','أسايس':'أساسي','وانتامئهم':'وانتمائهم','ترتتب':'تترتب','املؤلفني':'المؤلفين','العويف':'العوفي','مؤرش':'مؤشر','إجاميل':'إجمالي','األخري':'الأخير','ومل':'ولم','استغالل':'استغلال','إطالق':'إطلاق','االنفجارات':'الانفجارات','االرتفاع':'الارتفاع','االنخفاض':'الانخفاض','الغالف':'الغلاف','عالمة':'علامة','يعرب':'يعبر','املعلم':'المعلم','عارصت':'عاصرت','حسني':'حسين','قرص':'قصر','عرصين':'عصرين','المعارصون':'المعاصرون','املعارصون':'المعاصرون','تغيري':'تغيير','ترصيفها':'تصريفها','عرصها':'عصرها','الرباري':'البراري','الشهري':'الشهير','املخططني':'المخططين','املصطلحني':'المصطلحين','املوزعني':'الموزعين','املحميتني':'المحميتين'}
def fix2(s):
    from fixar import known,strip_h
    def f(m):
        w0=m.group(0); w=strip_h(w0)
        if w in W: return W[w]
        w=w.replace('عامن','عمان').replace('حامية','حماية').replace('امء','ماء')
        if not known(w) and 'رص' in w and known(w.replace('رص','صر')): w=w.replace('رص','صر')
        if not known(w) and len(w)>=5 and w.endswith('ني'): w=w[:-2]+'ين'
        if w!=strip_h(w0): return w
        mm=re.match(r'^([وفبكل]?)ا(م|إ|أ|آ|ا)ل(.*)$',w)
        if mm: return mm.group(1)+'ال'+mm.group(2)+mm.group(3)
        return w0
    s=AR.sub(f,s)
    s=re.sub(r'\s*\n\s*','\n',s).strip()
    return s
